      'conditions', x."conditions", 'actions', x."actions",
      'savedBy', x."saved_by", 'savedAt', x."saved_at"
    ) order by x."version" desc), '[]'::jsonb)
    from "better_supabase"."automation_versions" x where x."rule_id" = rule_versions_list.id
  );
